(()=>{'use strict';const timer=document.getElementById('countdown');function tick(){const now=new Date();let target=new Date(now.getFullYear()+'-12-25T00:00:00-03:00');if(now>=target)target=new Date((now.getFullYear()+1)+'-12-25T00:00:00-03:00');const seconds=Math.max(0,Math.floor((target-now)/1000));const days=Math.floor(seconds/86400);const hours=Math.floor(seconds%86400/3600);const minutes=Math.floor(seconds%3600/60);const secs=seconds%60;timer.textContent=days+'d '+String(hours).padStart(2,'0')+'h '+String(minutes).padStart(2,'0')+'m '+String(secs).padStart(2,'0')+'s'}tick();setInterval(tick,1000);const sticky=document.querySelector('.sticky'),hero=document.querySelector('.hero'),offer=document.getElementById('oferta');let heroVisible=true,offerVisible=false;if('IntersectionObserver'in window){const observer=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.target===hero)heroVisible=e.isIntersecting;else offerVisible=e.isIntersecting});sticky.classList.toggle('is-visible',!heroVisible&&!offerVisible)});observer.observe(hero);observer.observe(offer)}})();
